(function (global) {
    const PP_TooltipsLibrary = {
        counter: 0,

        init() {
            this.applyTooltips(document);
            this.bindGlobalClick();
        },

        nextTooltipId() {
            this.counter += 1;

            return 'tinypress-tooltip-' + this.counter;
        },

        toggle(tooltip) {
            const isActive = tooltip.classList.toggle('is-active');
            tooltip.setAttribute('aria-expanded', isActive ? 'true' : 'false');
        },

        applyTooltips(context = document) {
            const tooltips = context.querySelectorAll('[data-toggle="tooltip"].pp-tooltips-library');

            tooltips.forEach((tooltip) => {
                if (tooltip.dataset.tooltipProcessed === 'true') {
                    return;
                }

                const tooltipBox = tooltip.querySelector('.tooltip-text');

                if (!tooltipBox) {
                    return;
                }

                tooltip.dataset.tooltipProcessed = 'true';
                tooltipBox.id = tooltipBox.id || this.nextTooltipId();
                tooltipBox.setAttribute('role', 'tooltip');

                const focusTarget = tooltip.querySelector('a, button, input, select, textarea, [tabindex]:not([tabindex="-1"])');

                if (focusTarget) {
                    focusTarget.setAttribute('aria-describedby', tooltipBox.id);
                } else {
                    tooltip.tabIndex = 0;
                    tooltip.setAttribute('aria-describedby', tooltipBox.id);
                }

                if (! tooltipBox.querySelector('i')) {
                    const arrow = document.createElement('i');
                    arrow.setAttribute('aria-hidden', 'true');
                    tooltipBox.appendChild(arrow);
                }

                if (tooltip.classList.contains('click')) {
                    tooltip.setAttribute('aria-expanded', 'false');

                    if (! focusTarget) {
                        tooltip.setAttribute('role', 'button');
                    }

                    tooltip.addEventListener('click', (event) => {
                        if (event.target.closest('.clickable')) {
                            return;
                        }

                        event.preventDefault();
                        event.stopPropagation();
                        this.toggle(tooltip);
                    });

                    tooltip.addEventListener('keydown', (event) => {
                        if (focusTarget || (event.key !== 'Enter' && event.key !== ' ')) {
                            return;
                        }

                        event.preventDefault();
                        this.toggle(tooltip);
                    });
                }
            });
        },

        bindGlobalClick() {
            document.addEventListener('click', (event) => {
                const activeTooltip = event.target.closest('[data-toggle="tooltip"].pp-tooltips-library.click');

                if (activeTooltip && ! event.target.closest('.clickable')) {
                    return;
                }

                document.querySelectorAll('[data-toggle="tooltip"].pp-tooltips-library.click.is-active').forEach((tooltip) => {
                    tooltip.classList.remove('is-active');
                    tooltip.setAttribute('aria-expanded', 'false');
                });
            });
        },

        refresh(context = document) {
            this.applyTooltips(context);
        },
    };

    document.addEventListener('DOMContentLoaded', () => PP_TooltipsLibrary.init());
    global.PP_TooltipsLibrary = PP_TooltipsLibrary;
}(window));
